from __future__ import annotations

import json
from pathlib import Path

import numpy as np
import pytest
from scipy import sparse

from polaris.rl.rl_numpy_advanced import (
    ALL_POLICIES,
    GPU_DISABLED_R04,
    HybridPlacementAgent,
    HybridPlacementConfig,
    LargeScalePlacementConfig,
    LargeScalePlacementEnv,
    MultiObjectiveParetoReward,
    MultiObjectiveRewardConfig,
    POLICY_CURRICULUM,
    POLICY_HEURISTIC,
    POLICY_RANDOM,
    PPOAdvConfig,
    PPOAdvantageOptimizer,
    PretrainedPolicyConfig,
    PretrainedPolicyLibrary,
    _CANVAS_SIZE_UM,
    _GRID_CELL_SIZE_UM,
    _MIN_BEND_RADIUS_UM,
)


# ---------------------------------------------------------------------------
# 测试数据
# ---------------------------------------------------------------------------

_SIMPLE_CIRCUIT = {
    "devices": [
        {"id": "d0", "type": "mzi", "width": 50.0, "height": 30.0, "ports": ["p0", "p1"]},
        {"id": "d1", "type": "ring", "width": 40.0, "height": 40.0, "ports": ["p0", "p1"]},
        {"id": "d2", "type": "mmi", "width": 60.0, "height": 20.0, "ports": ["p0", "p1", "p2", "p3"]},
    ],
    "nets": [
        {"src": ["d0", "p1"], "dst": ["d1", "p0"], "type": "waveguide", "target_length": 100.0},
        {"src": ["d1", "p1"], "dst": ["d2", "p0"], "type": "waveguide", "target_length": 100.0},
    ],
}


def _make_large_circuit(n: int = 128) -> dict:
    """构造 n 个器件的大规模电路（R351 100+ 组件测试）。"""
    rng = np.random.default_rng(0)
    types = ["mzi", "ring", "mmi", "coupler"]
    devices = [
        {
            "id": f"dev{i}",
            "type": types[i % 4],
            "width": 50.0,
            "height": 30.0,
            "ports": [f"p{j}" for j in range(2 + (i % 3))],
        }
        for i in range(n)
    ]
    nets = []
    for i in range(n - 1):
        nets.append(
            {"src": [f"dev{i}", "p0"], "dst": [f"dev{i + 1}", "p0"], "type": "waveguide"}
        )
    rng.shuffle(nets)
    return {"devices": devices, "nets": nets}


# ===========================================================================
# 模块级：R04 纯 NumPy 声明 + 无 torch 依赖
# ===========================================================================


def test_module_r04_no_torch_dependency():
    """R04 合规：模块声明 GPU 禁用，且模块文件不 import torch。"""
    assert GPU_DISABLED_R04 is True
    src_path = Path(__file__).resolve().parents[1] / "src" / "polaris" / "rl" / "rl_numpy_advanced.py"
    src_text = src_path.read_text(encoding="utf-8")
    assert "import torch" not in src_text
    assert "from torch" not in src_text


# ===========================================================================
# R351 — LargeScalePlacementEnv（大规模电路支持）
# ===========================================================================


def test_r351_set_circuit_large_scale():
    """R351：128 器件电路设置成功（≥100 组件门槛）。"""
    env = LargeScalePlacementEnv(LargeScalePlacementConfig(grid_size=(32, 32)))
    circuit = _make_large_circuit(128)
    env.set_circuit(circuit)
    assert env.n_devices() == 128
    assert env.circuit is circuit


def test_r351_build_sparse_occupancy_empty():
    """R351：空布局占用栅格全零（CSR 稀疏）。"""
    env = LargeScalePlacementEnv()
    env.set_circuit(_SIMPLE_CIRCUIT)
    occ = env.build_sparse_occupancy()
    assert sparse.issparse(occ)
    assert occ.shape == (32, 32)
    assert occ.nnz == 0


def test_r351_build_sparse_occupancy_after_step():
    """R351：放置后占用栅格反映占用情况。"""
    env = LargeScalePlacementEnv()
    env.set_circuit(_SIMPLE_CIRCUIT)
    env.step("d0", 0)  # 放在 (row=0, col=0) → cell 占用
    occ = env.build_sparse_occupancy()
    assert occ.nnz > 0
    # d0 width=50 < 100 cell size, 只占用 (0,0) 单格
    assert occ[0, 0] == 1.0


def test_r351_build_state_shape():
    """R351：状态双轨表示 shape 正确（node_feats[N,9] / graph_summary[8]）。"""
    env = LargeScalePlacementEnv(LargeScalePlacementConfig(node_feat_dim=9))
    env.set_circuit(_SIMPLE_CIRCUIT)
    state = env.build_state(_SIMPLE_CIRCUIT["devices"][0])
    assert state["node_feats"].shape == (3, 9)
    assert state["graph_summary"].shape == (8,)
    assert state["action_mask"].shape == (32 * 32,)
    assert state["current_feat"].shape == (9,)
    # 空布局时 mask 全 1
    assert np.all(state["action_mask"] == 1.0)


def test_r351_step_updates_placement():
    """R351：step 放置器件并更新 placement。"""
    env = LargeScalePlacementEnv()
    env.set_circuit(_SIMPLE_CIRCUIT)
    env.step("d0", 5)
    # grid_idx=5 → row=0, col=5 → x=500, y=0
    assert env.placement["d0"]["x"] == pytest.approx(5 * _GRID_CELL_SIZE_UM)
    assert env.placement["d0"]["y"] == pytest.approx(0.0)


def test_r351_r03_set_circuit_invalid():
    """R351 R03：缺字段 / 空器件 / 超 max_devices 一律 raise。"""
    env = LargeScalePlacementEnv()
    with pytest.raises(ValueError, match="R03"):
        env.set_circuit({"devices": []})
    with pytest.raises(ValueError, match="R03"):
        env.set_circuit({"nets": []})  # 缺 devices
    env_max = LargeScalePlacementEnv(LargeScalePlacementConfig(max_devices=4))
    with pytest.raises(ValueError, match="超过 max_devices"):
        env_max.set_circuit(_make_large_circuit(8))


def test_r351_r03_step_conflict():
    """R351 R03：占用栅格冲突 / 重复放置 / 越界 一律 raise。"""
    env = LargeScalePlacementEnv()
    env.set_circuit(_SIMPLE_CIRCUIT)
    env.step("d0", 0)
    with pytest.raises(ValueError, match="已被占用"):
        env.step("d1", 0)  # 同一 cell 已被 d0 占用
    with pytest.raises(ValueError, match="已放置"):
        env.step("d0", 1)  # d0 重复放置
    with pytest.raises(ValueError, match="越界"):
        env.step("d1", 32 * 32)  # grid_idx 越界


# ===========================================================================
# R352 — PPOAdvantageOptimizer（PPO 优化）
# ===========================================================================


def test_r352_compute_gae_correctness():
    """R352：GAE 优势估计与回报手算结果一致（Schulman 2015 公式）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(gamma=0.99, gae_lambda=0.95))
    rewards = np.array([1.0, 2.0])
    values = np.array([0.5, 0.5])
    dones = np.array([0.0, 0.0])
    last_v = 0.0
    adv, ret = opt.compute_gae(rewards, values, dones, last_v)
    # t=1: δ = 2 + 0.99*0*1 - 0.5 = 1.5; Â_1 = 1.5
    # t=0: δ = 1 + 0.99*0.5*1 - 0.5 = 0.995; Â_0 = 0.995 + 0.99*0.95*1.5 = 2.40575
    assert adv[1] == pytest.approx(1.5, rel=1e-9)
    assert adv[0] == pytest.approx(2.40575, rel=1e-6)
    # returns = adv + values
    assert ret[0] == pytest.approx(2.40575 + 0.5, rel=1e-6)
    assert ret[1] == pytest.approx(1.5 + 0.5, rel=1e-9)


def test_r352_compute_gae_done_resets():
    """R352：done=1 时截断未来价值传递（ episode 边界）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(gamma=0.99, gae_lambda=0.95))
    rewards = np.array([1.0, 2.0, 3.0])
    values = np.array([0.5, 0.5, 0.5])
    dones = np.array([0.0, 1.0, 0.0])  # t=1 done
    adv, _ = opt.compute_gae(rewards, values, dones, last_v=0.0)
    # t=2: δ = 3 + 0.99*0 - 0.5 = 2.5; Â_2 = 2.5
    # t=1: δ = 2 + 0 - 0.5 = 1.5（done 截断）；Â_1 = 1.5
    # t=0: δ = 1 + 0.99*0.5*1 - 0.5 = 0.995; Â_0 = 0.995 + 0.99*0.95*1.5 = 2.40575
    assert adv[1] == pytest.approx(1.5, rel=1e-9)
    assert adv[0] == pytest.approx(2.40575, rel=1e-6)
    assert adv[2] == pytest.approx(2.5, rel=1e-9)


def test_r352_policy_loss_no_clip_when_ratio_one():
    """R352：new==old 时 ratio=1，policy_loss = -mean(adv)（Schulman 2017 Eq.7）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(clip_eps=0.2, ent_coef=0.0))
    adv = np.array([1.0, -1.0, 0.5])
    lp = np.zeros(3)  # new_logprob == old_logprob
    total_loss, metrics = opt.compute_policy_loss(lp, lp.copy(), adv, entropy=0.0)
    assert metrics["mean_ratio"] == pytest.approx(1.0, rel=1e-9)
    assert metrics["clip_frac"] == pytest.approx(0.0, rel=1e-9)
    assert metrics["policy_loss"] == pytest.approx(-np.mean(adv), rel=1e-9)
    assert total_loss == pytest.approx(-np.mean(adv), rel=1e-9)


def test_r352_policy_loss_entropy_bonus():
    """R352：熵正则化降低总损失（鼓励探索，Mnih 2016 A3C）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(ent_coef=0.01))
    adv = np.array([1.0, -1.0])
    lp = np.zeros(2)
    _, m_no_ent = opt.compute_policy_loss(lp, lp.copy(), adv, entropy=0.0)
    _, m_with_ent = opt.compute_policy_loss(lp, lp.copy(), adv, entropy=np.array([2.0, 2.0]))
    assert m_with_ent["entropy"] == pytest.approx(2.0, rel=1e-9)
    # 总损失 = policy_loss - ent_coef * entropy，熵为正则总损失降低
    assert m_with_ent["entropy"] > 0.0


def test_r352_value_loss_clipped():
    """R352：value loss clipped 形式正确（PPO clipped value loss）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(clip_eps=0.2, vf_coef=0.5))
    old_v = np.array([1.0, 1.0])
    new_v = np.array([5.0, 5.0])  # 超出 clip 范围
    ret = np.array([0.0, 0.0])
    loss = opt.compute_value_loss(new_v, old_v, ret)
    # v_clipped = 1.0 + clip(4.0, -0.2, 0.2)"""R351-R355 RL 布局布线增强模块单元测试。

