_SIMPLE_CIRCUIT = {
    "devices": [
        {"id": "d0", "type": "mzi", "width": 50.0, "height": 30.0, "ports": ["p0", "p1"]},
        {"id": "d1", "type": "ring", "width": 40.0, "height": 40.0, "ports": ["p0", "p1"]},
        {"id": "d2", "type": "mmi", "width": 60.0, "height": 20.0, "ports": ["p0", "p1", "p2", "p3"]},
    ],
    "nets": [
        {"src": ["d0", "p1"], "dst": ["d1", "p0"], "type": "waveguide", "target_length": 100.0},
        {"src": ["d1", "p1"], "dst": ["d2", "p0"], "type": "waveguide", "target_length": 100.0},
    ],
}


def _make_large_circuit(n: int = 128) -> dict:
    """构造 n 个器件的大规模电路（R351 100+ 组件测试）。"""
    rng = np.random.default_rng(0)
    types = ["mzi", "ring", "mmi", "coupler"]
    devices = [
        {
            "id": f"dev{i}",
            "type": types[i % 4],
            "width": 50.0,
            "height": 30.0,
            "ports": [f"p{j}" for j in range(2 + (i % 3))],
        }
        for i in range(n)
    ]
    nets = []
    for i in range(n - 1):
        nets.append(
            {"src": [f"dev{i}", "p0"], "dst": [f"dev{i + 1}", "p0"], "type": "waveguide"}
        )
    rng.shuffle(nets)
    return {"devices": devices, "nets": nets}


