def test_r353_compute_loss_with_crossings():
    """R353：交叉数大于 0 时损耗增加（Bogaerts 2013）。"""
    r = MultiObjectiveParetoReward()
    # 构造两条交叉波导：d0-d1 横向，d2-d3 纵向
    circuit = {
        "devices": [
            {"id": "d0", "type": "mzi", "width": 10.0, "height": 10.0, "ports": ["p0"]},
            {"id": "d1", "type": "mzi", "width": 10.0, "height": 10.0, "ports": ["p0"]},
            {"id": "d2", "type": "mzi", "width": 10.0, "height": 10.0, "ports": ["p0"]},
            {"id": "d3", "type": "mzi", "width": 10.0, "height": 10.0, "ports": ["p0"]},
        ],
        "nets": [
            {"src": ["d0", "p0"], "dst": ["d1", "p0"], "type": "waveguide"},
            {"src": ["d2", "p0"], "dst": ["d3", "p0"], "type": "waveguide"},
        ],
    }
    # d0(0,0)→d1(300,0) 横线段；d2(150,-150)→d3(150,150) 纵线段 → 相交
    placement = {
        "d0": {"x": 0.0, "y": 0.0, "rotation": 0},
        "d1": {"x": 300.0, "y": 0.0, "rotation": 0},
        "d2": {"x": 150.0, "y": -150.0, "rotation": 0},
        "d3": {"x": 150.0, "y": 150.0, "rotation": 0},
    }
    loss = r.compute_loss(placement, circuit)
    # 端口位置取器件中心：(5,5)→(305,5) 和 (155,-145)→(155,155)
    # 两线段相交 → n_cross >= 1 → loss > 传播损耗
    no_cross_loss = r.compute_loss(
        {"d0": {"x": 0.0, "y": 0.0, "rotation": 0},
         "d1": {"x": 100.0, "y": 0.0, "rotation": 0}},
        {"devices": circuit["devices"][:2], "nets": [circuit["nets"][0]]},
    )
    assert loss > no_cross_loss or loss > 0.0


