def test_r353_pareto_front_nsga2():
    """R353：NSGA-II 非支配排序（Deb 2002）正确识别 Pareto 前沿。"""
    r = MultiObjectiveParetoReward()
    # 三解：[1,2] [2,1] [3,3]（最小化）
    # [3,3] 被 [1,2] 与 [2,1] 支配，前沿 = {[1,2], [2,1]}
    obj = np.array([[1.0, 2.0], [2.0, 1.0], [3.0, 3.0]])
    front = r.pareto_front(obj, maximize=False)
    assert set(front.tolist()) == {0, 1}
    # 最大化场景：[3,3] 支配另两者，前沿 = {[3,3]}
    front_max = r.pareto_front(obj, maximize=True)
    assert set(front_max.tolist()) == {2}


