def test_r351_r03_step_conflict():
    """R351 R03：占用栅格冲突 / 重复放置 / 越界 一律 raise。"""
    env = LargeScalePlacementEnv()
    env.set_circuit(_SIMPLE_CIRCUIT)
    env.step("d0", 0)
    with pytest.raises(ValueError, match="已被占用"):
        env.step("d1", 0)  # 同一 cell 已被 d0 占用
    with pytest.raises(ValueError, match="已放置"):
        env.step("d0", 1)  # d0 重复放置
    with pytest.raises(ValueError, match="越界"):
        env.step("d1", 32 * 32)  # grid_idx 越界


# ===========================================================================
# R352 — PPOAdvantageOptimizer（PPO 优化）
# ===========================================================================


def test_r352_compute_gae_correctness():
    """R352：GAE 优势估计与回报手算结果一致（Schulman 2015 公式）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(gamma=0.99, gae_lambda=0.95))
    rewards = np.array([1.0, 2.0])
    values = np.array([0.5, 0.5])
    dones = np.array([0.0, 0.0])
    last_v = 0.0
    adv, ret = opt.compute_gae(rewards, values, dones, last_v)
    # t=1: δ = 2 + 0.99*0*1 - 0.5 = 1.5; Â_1 = 1.5
    # t=0: δ = 1 + 0.99*0.5*1 - 0.5 = 0.995; Â_0 = 0.995 + 0.99*0.95*1.5 = 2.40575
    assert adv[1] == pytest.approx(1.5, rel=1e-9)
    assert adv[0] == pytest.approx(2.40575, rel=1e-6)
    # returns = adv + values
    assert ret[0] == pytest.approx(2.40575 + 0.5, rel=1e-6)
    assert ret[1] == pytest.approx(1.5 + 0.5, rel=1e-9)


def test_r352_compute_gae_done_resets():
    """R352：done=1 时截断未来价值传递（ episode 边界）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(gamma=0.99, gae_lambda=0.95))
    rewards = np.array([1.0, 2.0, 3.0])
    values = np.array([0.5, 0.5, 0.5])
    dones = np.array([0.0, 1.0, 0.0])  # t=1 done
    adv, _ = opt.compute_gae(rewards, values, dones, last_v=0.0)
    # t=2: δ = 3 + 0.99*0 - 0.5 = 2.5; Â_2 = 2.5
    # t=1: δ = 2 + 0 - 0.5 = 1.5（done 截断）；Â_1 = 1.5
    # t=0: δ = 1 + 0.99*0.5*1 - 0.5 = 0.995; Â_0 = 0.995 + 0.99*0.95*1.5 = 2.40575
    assert adv[1] == pytest.approx(1.5, rel=1e-9)
    assert adv[0] == pytest.approx(2.40575, rel=1e-6)
    assert adv[2] == pytest.approx(2.5, rel=1e-9)


def test_r352_policy_loss_no_clip_when_ratio_one():
    """R352：new==old 时 ratio=1，policy_loss = -mean(adv)（Schulman 2017 Eq.7）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(clip_eps=0.2, ent_coef=0.0))
    adv = np.array([1.0, -1.0, 0.5])
    lp = np.zeros(3)  # new_logprob == old_logprob
    total_loss, metrics = opt.compute_policy_loss(lp, lp.copy(), adv, entropy=0.0)
    assert metrics["mean_ratio"] == pytest.approx(1.0, rel=1e-9)
    assert metrics["clip_frac"] == pytest.approx(0.0, rel=1e-9)
    assert metrics["policy_loss"] == pytest.approx(-np.mean(adv), rel=1e-9)
    assert total_loss == pytest.approx(-np.mean(adv), rel=1e-9)


def test_r352_policy_loss_entropy_bonus():
    """R352：熵正则化降低总损失（鼓励探索，Mnih 2016 A3C）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(ent_coef=0.01))
    adv = np.array([1.0, -1.0])
    lp = np.zeros(2)
    _, m_no_ent = opt.compute_policy_loss(lp, lp.copy(), adv, entropy=0.0)
    _, m_with_ent = opt.compute_policy_loss(lp, lp.copy(), adv, entropy=np.array([2.0, 2.0]))
    assert m_with_ent["entropy"] == pytest.approx(2.0, rel=1e-9)
    # 总损失 = policy_loss - ent_coef * entropy，熵为正则总损失降低
    assert m_with_ent["entropy"] > 0.0


def test_r352_value_loss_clipped():
    """R352：value loss clipped 形式正确（PPO clipped value loss）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(clip_eps=0.2, vf_coef=0.5))
    old_v = np.array([1.0, 1.0])
    new_v = np.array([5.0, 5.0])  # 超出 clip 范围
    ret = np.array([0.0, 0.0])
    loss = opt.compute_value_loss(new_v, old_v, ret)
    # v_clipped = 1.0 + clip(4.0, -0.2, 0.2) = 1.2
    # loss1 = (5-0)^2 = 25; loss2 = (1.2-0)^2 = 1.44; max = 25
    # 0.5 * mean(25) = 12.5
    assert loss == pytest.approx(12.5, rel=1e-9)


def test_r352_cosine_lr_schedule_endpoints():
    """R352：余弦退火 LR 在 step=0 取 initial_lr，step=total 取 min_lr（Loshchilov 2017 SGDR）。"""
    opt = PPOAdvantageOptimizer(PPOAdvConfig(initial_lr=3e-4, min_lr=1e-5))
    assert opt.cosine_lr_schedule(0, 100) == pytest.approx(3e-4, rel=1e-6)
    assert opt.cosine_lr_schedule(100, 100) == pytest.approx(1e-5, rel=1e-6)
    mid = opt.cosine_lr_schedule(50, 100)
    assert 1e-5 < mid < 3e-4


def test_r352_update_end_to_end():
    """R352：端到端 PPO 更新输出含全部关键字段。"""
    opt = PPOAdvantageOptimizer()
    T = 8
    rollout = {
        "rewards": np.random.default_rng(0).standard_normal(T),
        "values": np.random.default_rng(1).standard_normal(T),
        "old_logprobs": np.random.default_rng(2).standard_normal(T),
        "old_values": np.random.default_rng(3).standard_normal(T),
        "dones": np.zeros(T),
        "last_value": 0.0,
    }
    new_lp = rollout["old_logprobs"] + 0.01
    new_v = rollout["old_values"] + 0.01
    result = opt.update(rollout, new_lp, new_v, entropy=0.5)
    for key in ("advantages", "returns", "policy_loss", "value_loss",
                "total_loss", "clip_frac", "entropy"):
        assert key in result
    assert result["advantages"].shape == (T,)
    assert result["returns"].shape == (T,)


def test_r352_r03_invalid_inputs():
    """R352 R03：形状不匹配 / 空数组 / total_steps<=0 一律 raise。"""
    opt = PPOAdvantageOptimizer()
    with pytest.raises(ValueError, match="形状不匹配"):
        opt.compute_gae(np.array([1.0]), np.array([1.0, 2.0]), np.array([0.0]))
    with pytest.raises(ValueError, match="R03"):
        opt.compute_gae(np.array([]), np.array([]), np.array([]))
    with pytest.raises(ValueError, match="R03"):
        opt.compute_policy_loss(np.array([]), np.array([]), np.array([]))
    with pytest.raises(ValueError, match="R03"):
        opt.cosine_lr_schedule(0, 0)


