def test_r354_list_three_policies():
    """R354：策略库提供 3 种基础策略（heuristic/random/curriculum）。"""
    lib = PretrainedPolicyLibrary()
    policies = lib.list_policies()
    assert set(policies) == {POLICY_HEURISTIC, POLICY_RANDOM, POLICY_CURRICULUM}
    assert ALL_POLICIES == (POLICY_HEURISTIC, POLICY_RANDOM, POLICY_CURRICULUM)


def test_r354_generate_placement_heuristic():
    """R354：启发式策略生成完整布局（高连接度优先放中心）。"""
    lib = PretrainedPolicyLibrary()
    placement = lib.generate_placement(_SIMPLE_CIRCUIT, POLICY_HEURISTIC)
    assert len(placement) == 3
    for dev in _SIMPLE_CIRCUIT["devices"]:
        assert dev["id"] in placement
        p = placement[dev["id"]]
        assert 0 <= p["x"] <= _CANVAS_SIZE_UM
        assert 0 <= p["y"] <= _CANVAS_SIZE_UM
        assert p["rotation"] == 0
    # d1 连接度最高（=2），应被放在最接近中心的格子
    cache = lib.get_policy_cache(POLICY_HEURISTIC)
    assert cache["n_devices"] == 3


